#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>
#include <climits>
#include <cstring>

using namespace std;

struct Location {
    int r, c;
    Location(int _r=0, int _c=0): r(_r), c(_c) {}
};

int dr[] = {-1, 0, 0, 1};
int dc[] = {0, -1, 1, 0};

int sizeN, maxT;
char maze[12][12], mazeA[12][12], mazeB[12][12];
int distA[12][12], distB[12][12];

void compute_distance_A(const Location& start) {
    memset(distA, -1, sizeof(distA));
    distA[start.r][start.c] = 0;
    queue<Location> q;
    q.push(start);
    while (!q.empty()) {
        Location p = q.front(); q.pop();
        for (int k=0; k<4; ++k) {
            Location np(p.r + dr[k], p.c + dc[k]);
            if (maze[np.r][np.c] != '.') continue;
            if (distA[np.r][np.c] < 0) {
                distA[np.r][np.c] = distA[p.r][p.c] + 1;
                q.push(np);
            }
        }
    }
}

void compute_distance_B(const Location& start) {
    memset(distB, -1, sizeof(distB));
    distB[start.r][start.c] = 0;
    queue<Location> q;
    q.push(start);
    while (!q.empty()) {
        Location p = q.front(); q.pop();
        if (distA[p.r][p.c] >= 0 && distB[p.r][p.c] >= distA[p.r][p.c]) continue;
        for (int k=0; k<4; ++k) {
            Location np(p.r + dr[k], p.c + dc[k]);
            if (maze[np.r][np.c] != '.') continue;
            if (distB[np.r][np.c] < 0) {
                if (distA[np.r][np.c] >= 0 && distA[np.r][np.c] < distB[p.r][p.c] + 1) continue;
                distB[np.r][np.c] = distB[p.r][p.c] + 1;
                q.push(np);
            }
        }
    }
}

struct Network {
    int n;
    vector<vector<int>> capacity, flow;
    vector<int> parent, level;

    Network(int size): n(size), capacity(size, vector<int>(size,0)), flow(size, vector<int>(size,0)), parent(size), level(size) {}

    void addEdge(int u, int v, int c) {
        capacity[u][v] += c;
    }

    int bfs(int s, int t, vector<int>& path) {
        fill(parent.begin(), parent.end(), -1);
        fill(level.begin(), level.end(), -1);
        level[s]=0;
        queue<int> q;
        q.push(s);
        while (!q.empty()) {
            int u=q.front(); q.pop();
            if (u==t) {
                int minCap=INT_MAX;
                for (int v=t; v!=s; v=parent[v]) {
                    minCap = min(minCap, capacity[parent[v]][v]-flow[parent[v]][v]);
                }
                path.clear();
                for (int v=t; v!=s; v=parent[v]) path.push_back(v);
                path.push_back(s);
                reverse(path.begin(), path.end());
                return minCap;
            }
            for (int v=0; v<n; ++v) {
                if (parent[v]<0 && capacity[u][v]-flow[u][v]>0) {
                    parent[v]=u;
                    level[v]=level[u]+1;
                    q.push(v);
                }
            }
        }
        return 0;
    }

    int maxFlow(int s, int t) {
        int total=0;
        vector<int> p;
        while (int push=bfs(s,t,p)) {
            for (size_t i=0; i+1<p.size(); ++i) {
                int u=p[i], v=p[i+1];
                flow[u][v]+=push;
                flow[v][u]-=push;
            }
            total+=push;
        }
        return total;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> sizeN >> maxT;
    memset(mazeA, '#', sizeof(mazeA));
    for (int r=1; r<=sizeN; ++r) {
        cin >> (mazeA[r]+1);
        mazeA[r][sizeN+1]='#';
    }
    memset(mazeB, '#', sizeof(mazeB));
    for (int r=1; r<=sizeN; ++r) {
        cin >> (mazeB[r]+1);
        mazeB[r][sizeN+1]='#';
    }
    memset(maze, '#', sizeof(maze));
    vector<Location> scientists, capsules;
    Location z;
    for (int r=1; r<=sizeN; ++r) {
        for (int c=1; c<=sizeN; ++c) {
            if (isdigit(mazeA[r][c])) {
                if (mazeA[r][c]>'0') scientists.emplace_back(r,c);
                maze[r][c]='.';
            } else if (mazeA[r][c]=='Z') {
                z=Location(r,c);
                maze[r][c]='.';
            }
            if (isdigit(mazeB[r][c]) && mazeB[r][c]>'0') {
                capsules.emplace_back(r,c);
            }
        }
    }
    compute_distance_A(z);
    int s=0;
    int t= (int)scientists.size() + (int)capsules.size() + 1;
    Network net(t+1);
    for (int i=0; i<(int)scientists.size(); ++i) {
        net.addEdge(s, i+1, mazeA[scientists[i].r][scientists[i].c]-'0');
    }
    for (int j=0; j<(int)capsules.size(); ++j) {
        net.addEdge((int)scientists.size()+j+1, t, mazeB[capsules[j].r][capsules[j].c]-'0');
    }
    for (int i=0; i<(int)scientists.size(); ++i) {
        compute_distance_B(scientists[i]);
        for (int j=0; j<(int)capsules.size(); ++j) {
            if (distB[capsules[j].r][capsules[j].c]>=0 && distB[capsules[j].r][capsules[j].c]<=maxT)
                net.addEdge(i+1, (int)scientists.size()+j+1, INT_MAX);
        }
    }
    int answer=net.maxFlow(s,t);
    cout << answer << "\n";
    return 0;
}
